(() => {
    'use strict';
    const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const paths={back:'m14 5-7 7 7 7',next:'M12 4v16m-6-6 6 6 6-6',right:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',more:'M5 12h.01M12 12h.01M19 12h.01',book:'M3 5c3-1 6-1 9 1v15c-3-2-6-2-9-1V5Zm18 0c-3-1-6-1-9 1v15c3-2 6-2 9-1V5Z',bookmark:'M6 3h12v18l-6-4-6 4V3Z',library:'M5 4v16M10 4v16M15 5l4 14',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',plus:'M12 4v16M4 12h16',share:'M12 15V2m-4 4 4-4 4 4M5 10v10h14V10',sliders:'M4 7h16M4 17h16M8 4v6M16 14v6',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',check:'m5 12 4 4L19 6',play:'m9 5 11 7-11 7V5Z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrowup:'M12 20V4m-6 6 6-6 6 6'};
    const icon=n=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="'+(n==='more'?3:1.7)+'" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[n]||paths.more)+'"/></svg>';
    const mark='<svg viewBox="0 0 64 64" aria-hidden="true"><path fill="currentColor" fill-rule="evenodd" transform="translate(0 64) scale(1 -1)" d="M32 6C17 6 7 17 7 32s10 26 25 26l25-25C57 17 47 6 32 6Zm0 9c10 0 16 7 16 17H33v17c-10 1-17-6-17-17 0-10 6-17 16-17Z"/></svg>';
    const fonts=[{id:'newsreader',name:'Newsreader',css:'Newsreader',note:'The original Afterglow voice'},{id:'source',name:'Source Serif',css:'SourceSerif',note:'Sturdy, quiet, even'},{id:'literata',name:'Literata',css:'Literata',note:'Open forms, a bookish rhythm'},{id:'lora',name:'Lora',css:'Lora',note:'Lively curves, firm structure'},{id:'fraunces',name:'Fraunces',css:'Fraunces',note:'Soft edges, more personality'},{id:'crimson',name:'Crimson Pro',css:'Crimson',note:'A compact, literary voice'}];
    const articles=OTIUM_CONTENT.articles;
    const video={id:'video',source:'Motion study',author:'Illustrative media',title:'Where the mountains meet the water',dateLabel:'Video preview',topic:'Outdoors',teaser:'An inset player, some space around it, and nothing starting until you choose to watch.',image:'assets/landscape.jpg',kind:'video'};
    const items=[...articles,video];
    const defaults={font:'fraunces',match:false,eink:false,audition:false,readingSize:19,saved:{'404media':['Read later']},collections:['Read later','Watch later'],duration:10,scope:'Everything',excluded:[],sourcePrefs:{},customSources:[],history:[],cursor:0,active:false,phase:'settle',started:0,savedAt:{'404media':1},readerOrigin:'session',sessionIds:null,sessionPlan:null,sessionOpened:[],furthest:0};
    let state={...defaults};try{const old=JSON.parse(localStorage.getItem('otium-afterglow-study')||'null');if(old)state={...defaults,...old};}catch{}
    if(state.typeRevision!==3){state.font='fraunces';state.match=false;state.audition=false;state.typeRevision=3;}
    const params=new URLSearchParams(location.search);if(fonts.some(f=>f.id===params.get('font')))state.font=params.get('font');if(params.has('eink'))state.eink=params.get('eink')==='1';if(params.has('audition'))state.audition=params.get('audition')!=='0';
    state.cursor=Math.min(items.length-1,Math.max(0,state.cursor));
    let instrumentRole='',route='',origin=state.readerOrigin||'session',previousFocus=null,toastTimer,observer,rendering=false,importDraft=[],sort='saved',historyFilter='Read',phasePreview=false;
    const main=$('#main'),sheet=$('#sheet'),top=$('#top'),bottom=$('#bottom'),viewer=$('#image-viewer');
    let viewerFocus=null;
    const persist=()=>{try{localStorage.setItem('otium-afterglow-study',JSON.stringify(state));}catch{}};
    const sessionItems=()=>state.sessionIds?state.sessionIds.map(id=>items.find(a=>a.id===id)).filter(Boolean):items;
    const current=()=>sessionItems()[state.cursor]||items[0];
    const article=id=>items.find(x=>x.id===id)||current();
    function toast(message){const el=$('#notice');clearTimeout(toastTimer);el.textContent=message;el.className='on';toastTimer=setTimeout(()=>el.className='',2200);}
    function pause(){document.querySelectorAll('video,audio').forEach(v=>v.pause());}
    function closeSheet(restore=true){sheet.close();if(restore&&previousFocus?.isConnected)previousFocus.focus({preventScroll:true});}
    function showSheet(title,html){pause();if(!sheet.open)previousFocus=document.activeElement;sheet.innerHTML='<header class="sheet-head"><h2 id="sheet-title">'+esc(title)+'</h2><button class="icon-button soft" data-action="close" aria-label="Close">'+icon('close')+'</button></header><div class="sheet-body">'+html+'</div>';if(!sheet.open)sheet.showModal();}
    const btn=(label,action,cls='primary',ic='')=>'<button class="'+cls+'" data-action="'+esc(action)+'">'+(ic?icon(ic):'')+label+'</button>';
    const row=(label,action,ic='chevron',sub='',value='')=>'<button class="row" data-action="'+esc(action)+'">'+icon(ic)+'<span class="copy">'+label+(sub?'<small>'+sub+'</small>':'')+'</span>'+(value?'<span class="value">'+value+'</span>':'')+icon('chevron')+'</button>';
    const field=(label,name,value='',type='text')=>'<label class="field" for="'+name+'">'+label+'</label><input id="'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" required>';
    const itemRow=a=>'<button class="item-row" data-action="read:'+a.id+'"><img src="'+a.image+'" alt=""><span class="copy"><small>'+esc(a.source)+' · '+a.dateLabel+'</small><strong>'+esc(a.title)+'</strong></span></button>';
    const resume=()=>state.active?'<button class="resume" data-action="nav:session"><span>Return to your session<small>Your place is waiting.</small></span>'+icon('right')+'</button>':'';
    function applyFont(){const f=fonts.find(f=>f.id===state.font)||fonts[0];document.documentElement.style.setProperty('--heading',f.css+',Georgia,serif');document.documentElement.style.setProperty('--reader',(state.match?f.css:'Newsreader')+',Georgia,serif');document.documentElement.style.setProperty('--reading-size',state.readingSize+'px');document.body.dataset.eink=String(state.eink);renderFontBar();document.fonts.ready.then(fitBriefs);persist();}
    function renderFontBar(){const focusAction=document.activeElement?.closest('#fontbar')?document.activeElement.dataset.action:null;let el=$('#fontbar');if(!el){el=document.createElement('div');el.id='fontbar';top.after(el);}el.hidden=!state.audition;const f=fonts.find(f=>f.id===state.font)||fonts[0];el.innerHTML='<button class="icon-button" data-action="font-prev" aria-label="Previous typeface">'+icon('back')+'</button><button class="font-now" data-action="typography"><small>Typeface preview</small><span style="font-family:'+f.css+'">'+f.name+'</span></button><button class="icon-button" data-action="font-next" aria-label="Next typeface">'+icon('chevron')+'</button><button class="icon-button" data-action="audition-close" aria-label="Hide typeface preview">'+icon('close')+'</button>';if(focusAction)el.querySelector('[data-action="'+focusAction+'"]')?.focus({preventScroll:true});}
    function typography() {
        showSheet('Type & reading','<p class="fine">The selected Afterglow pairing.</p><div class="font-preview"><div class="lab-label">Fraunces · titles</div><h3 style="font-family:Fraunces">Make a little room.</h3><div class="lab-label" style="margin-top:24px">Newsreader · reading</div><p style="font-family:Newsreader">A few good things from the sources you chose. One at a time, with space to pay attention.</p></div>'+row('Reading size','reading-size','sliders','Keep the page comfortable',state.readingSize+'px')+row('Appearance','nav:appearance','sun','E-ink and reading preferences')+row('Explore this study','study','book','Screens, gestures and design notes')+btn('Done','close','primary'));
    }
    const motionAllowed=()=>!state.eink&&!matchMedia('(prefers-reduced-motion:reduce)').matches;
    function revealImage(id) {
        const a=article(id);if(a.kind==='video')return;
        pause();if(sheet.open)closeSheet();viewerFocus=document.activeElement;
        viewer.innerHTML='<header class="image-viewer-head"><span>'+mark+'</span><div><h2 id="image-title">The whole picture</h2><p>'+esc(a.source)+'</p></div><button class="icon-button" data-action="image-close" aria-label="Close full image">'+icon('close')+'</button></header><div class="image-stage"><img src="'+a.image+'" alt="Full article image from '+esc(a.source)+'"></div><footer class="image-viewer-foot"><p>'+esc(a.imageCredit||'Publisher image')+'</p><span>Pinch to look closer</span></footer>';
        viewer.showModal();
    }
    function closeImage(restore=true){if(viewer.open)viewer.close();if(restore&&viewerFocus?.isConnected)viewerFocus.focus({preventScroll:true});}
    function canAdvanceReader(){return route.startsWith('reader/')&&origin==='session'&&state.active&&route.slice(7)===current().id;}
    function advanceReader(){if(canAdvanceReader())next();}
    function navigate(next){if(sheet.open)closeSheet();if(viewer.open)closeImage();pause();if(next===route){render();return;}window.history.pushState({otiumFrom:route},'', '#'+next);render();}
    function goBack(){const parts=route.split('/');if(parts[0]==='reader'){if(window.history.state?.otiumFrom===origin)window.history.back();else navigate(origin);}else if(parts[0]==='setup-topics')navigate('setup');else if(parts[0]==='setup')navigate('start');else if(parts[0]==='topic')navigate(['Outdoors','Culture'].includes(parts[1])?'section/outdoors':'section/news');else if(parts[0]==='source')navigate('library');else if(parts[0]==='collection')navigate('saved');else if(['history','insights','settings','appearance'].includes(parts[0]))navigate('you');else navigate('home');}
    function header(title,back=true){top.innerHTML=(back?'<button class="icon-button" data-action="back" aria-label="Back">'+icon('back')+'</button><span class="top-title">'+esc(title)+'</span>':'<a class="brand" href="#home" aria-label="Otium home">'+mark+'<span>otium</span></a>')+(route==='session'?'<button class="top-link" data-action="nav:library">Library</button>':'<button class="icon-button" data-action="app-menu" aria-label="App menu">'+icon('more')+'</button>')+'<button class="font-button" data-action="typography" aria-label="Type and reading">Aa</button>';renderFontBar();}
    function instrument({left='more',leftAction='app-menu',label,sub='',action='session-menu',right='',rightAction='',rightIcon='',accent=false}) {
        const role=route.split('/')[0],mode=role==='session'?'session':role==='reader'?'reader':'app';
        const names={session:'Session',reader:'Article',home:'Otium',start:'New session',setup:'Choose time','setup-topics':'Choose topics',you:'Your Otium',history:'History',insights:'Insights',appearance:'Appearance',settings:'Settings',library:'Library',section:'Section',topic:'Topic',source:'Source',saved:'Saved',collection:'Collection',add:'Add source',import:'Import',end:'Session complete'};
        const changed=instrumentRole&&instrumentRole!==role;
        bottom.hidden=false;bottom.dataset.mode=mode;
        bottom.innerHTML='<div class="instrument">'+(left?'<button class="context" data-action="'+leftAction+'" aria-label="'+(leftAction==='article-menu'?'Article options':leftAction==='save'?'Save to collections':'Context options')+'">'+icon(left)+'</button>':'')+'<button class="meaning '+(!left?'only':'')+'" data-action="'+action+'" title="'+esc(sub)+'"><small class="instrument-mode">'+mark+'<span>'+esc(names[role]||'Otium')+'</span></small><span class="instrument-label">'+label+'</span></button>'+(right?'<button class="go '+(accent?'accent':'')+'" data-action="'+rightAction+'">'+right+(rightIcon?icon(rightIcon):'')+'</button>':'')+'</div>';
        if(changed&&motionAllowed())bottom.querySelectorAll('.meaning,.go').forEach(el=>el.animate([{opacity:.25,transform:'translateX(9px)'},{opacity:1,transform:'translateX(0)'}],{duration:180,easing:'ease-out'}));
        instrumentRole=role;
    }
    function appInstrument(label) {
        instrument({left:'more',leftAction:'app-menu',label,action:'app-menu',right:state.active?'Resume':'Start',rightAction:state.active?'nav:session':'nav:setup',rightIcon:state.active?'play':'right'});
    }
    function phrase(){return {settle:'Time to settle in',middle:'A little time left',last:'Room for one more',ended:'A good place to stop'}[state.phase]||'A little time left';}
    function sessionInstrument(){instrument({left:'more',leftAction:'article-menu',label:phrase(),sub:'Your reading session',action:'session-menu',right:'Next',rightAction:'next',rightIcon:'next'});}
    function scopeTopics(scope=state.scope) {
        return scope==='News & ideas'?['Vermont','Politics','Technology']:scope==='A wider world'?['Outdoors']:scope==='Vermont'?['Vermont']:['Vermont','Politics','Technology','Outdoors'];
    }
    function plannedItems() {
        const topics=scopeTopics().filter(t=>!state.excluded.includes(t));
        return ['vtdigger','politico','404media','video','long-title'].map(id=>items.find(a=>a.id===id))
            .filter(a=>topics.includes(a.topic)).slice(0,Math.max(1,Math.ceil(state.duration/3)));
    }
    function setPosition(index) {
        state.cursor=index;
        state.furthest=Math.max(state.furthest||0,index);
        if(state.sessionPlan&&!phasePreview) {
            const total=sessionItems().length;
            state.phase=state.furthest>=total-1&&total>1?'last':state.furthest>0?'middle':'settle';
            sessionInstrument();
        }
        persist();
    }
    function finishSession() {state.active=false;persist();navigate('end');}
    function begin() {
        const selected=plannedItems();
        if(!selected.length){toast('Choose at least one topic to bring with you');return;}
        state.sessionIds=selected.map(a=>a.id);
        state.sessionPlan={duration:state.duration,scope:state.scope,excluded:[...state.excluded]};
        state.sessionOpened=[];state.furthest=0;state.active=true;state.cursor=0;
        state.phase='settle';state.started=Date.now();phasePreview=false;persist();navigate('session');
    }
    function next() {
        pause();
        if(state.cursor>=sessionItems().length-1||state.phase==='ended'){finishSession();return;}
        setPosition(state.cursor+1);
        if(route==='session')main.querySelectorAll('.brief-page')[state.cursor].scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches||state.eink?'instant':'smooth'});
        else navigate('session');
    }
    function fitBriefs() {
        if(route!=='session')return;
        main.querySelectorAll('.brief-page').forEach(page=>{
            const h=page.querySelector('h1'),media=page.querySelector('.media');
            page.classList.remove('compact');h.style.fontSize='';media.style.height='';
            page.style.setProperty('--title-lines',4);page.style.setProperty('--blurb-lines',3);
            const base=parseFloat(getComputedStyle(h).fontSize);
            const overflow=()=>page.querySelector('.brief').getBoundingClientRect().height>page.clientHeight-parseFloat(getComputedStyle(page).paddingTop)-parseFloat(getComputedStyle(page).paddingBottom)+1;
            if(overflow())page.classList.add('compact');
            for(let size=base-1;size>=24&&overflow();size--)h.style.fontSize=size+'px';
            if(overflow())page.style.setProperty('--blurb-lines',2);
            let height=media.getBoundingClientRect().height;
            while(overflow()&&height>140){height-=4;media.style.height=height+'px';}
            if(overflow())page.style.setProperty('--title-lines',3);
            while(overflow()&&height>112){height-=4;media.style.height=height+'px';}
            page.dataset.overflow=String(overflow());
        });
    }
    function session() {
        if(!state.sessionPlan)state.active=true;
        if(!state.active&&state.sessionPlan){navigate('start');return;}
        header('',false);main.className='session';
        main.innerHTML=sessionItems().map((a,i)=>'<section class="brief-page" data-index="'+i+'" '+(!a.kind?'data-open="'+a.id+'"':'')+' aria-label="'+esc(a.source)+' brief"><article class="brief"><div class="source-label">'+esc(a.source)+'</div><div class="byline">'+esc(a.author)+' · '+a.dateLabel+'</div><h1>'+(!a.kind?'<a class="headline-link" href="#reader/'+a.id+'" data-action="read:'+a.id+'">'+esc(a.title)+'</a>':esc(a.title))+'</h1><figure class="media" style="--image-ratio:'+(a.kind?'1.7778':a.imageWidth/a.imageHeight)+'">'+(a.kind==='video'?'<video controls playsinline preload="none" poster="'+a.image+'" src="assets/landscape-demo.mp4" aria-label="Illustrative landscape video"></video>':'<img data-full-image="'+a.id+'" src="'+a.image+'" alt="Article image from '+esc(a.source)+'" draggable="false">')+'</figure><p class="blurb">'+esc(a.teaser)+'</p>'+(a.kind?btn('About this preview','media-notes','secondary read-action'): '<span class="read-action" aria-hidden="true">Read the story '+icon('right')+'</span>')+'</article></section>').join('')+'<section class="end-page" data-index="'+sessionItems().length+'"><h2>A good place to stop.</h2></section>';
        sessionInstrument();
        observer=new IntersectionObserver(entries=>entries.forEach(e=>{
            if(e.isIntersecting&&!rendering){const index=Number(e.target.dataset.index);if(index===sessionItems().length||(index>state.cursor&&state.phase==='ended')){finishSession();return;}setPosition(index);}
            if(!e.isIntersecting)e.target.querySelector('video')?.pause();
        }),{root:main,threshold:.65});
        main.querySelectorAll('.brief-page,.end-page').forEach(x=>observer.observe(x));
        main.querySelectorAll('img').forEach(x=>x.addEventListener('load',fitBriefs));
        fitBriefs();main.scrollTop=state.cursor*main.clientHeight;setTimeout(()=>{rendering=false;},150);
    }
    function home(){header('',false);main.innerHTML='<div class="content"><p class="eyebrow">Afterglow</p><h1>Make a little room.</h1><p class="lede">Something worth reading.<br>Some time of your own.</p><div class="group">'+row('Start a new session','nav:setup','book','Set the time. Choose what comes with you.')+row('Your library','nav:library','library','Sources, topics, and the balance between them.')+row('Saved for later','nav:saved','bookmark','A place to come back to.')+row('Your Otium','nav:you','person','Reading history, preferences, and perspective.')+'</div><p class="fine">Afterglow study. Account changes stay on this device.</p></div>';instrument({left:'clock',leftAction:'nav:setup',label:state.active?'Your place is waiting':'Ready when you are',sub:state.active?'Return without losing your article':'Choose a little time',action:state.active?'nav:session':'nav:setup',right:state.active?'Resume':'Begin',rightAction:state.active?'nav:session':'nav:setup',rightIcon:'right',accent:true});}
    function start() {
        header('',false);
        main.innerHTML='<div class="content start-screen"><p class="eyebrow">A little time of your own</p><h1>Make a little room.</h1><p class="lede">A few good things from the sources you chose. One at a time.</p><div class="start-photos" aria-hidden="true">'+[articles[0],articles[2],video].map(a=>'<img src="'+a.image+'" alt="">').join('')+'</div><p class="start-thought">Choose how long you have.<br>Bring what interests you.<br>Leave the rest for another time.</p>'+(state.active?resume():'')+'<p class="fine">Interactive preview with sample content. Nothing changes in your account.</p></div>';
        instrument({left:'clock',leftAction:'nav:setup',label:'Ready when you are',sub:'Start a new session',action:'nav:setup',right:'Choose',rightAction:'nav:setup',rightIcon:'right',accent:true});
    }
    function setup() {
        header('A little time');
        main.innerHTML='<div class="content setup-screen"><p class="eyebrow">First, a little time</p><h1>How much room<br>do you have?</h1><p class="lede">An intention, not a deadline.</p><div class="choice-grid">'+[[5,'A small pause'],[10,'A little time'],[20,'A quiet break'],[40,'Room to wander']].map(([n,t])=>'<button class="choice" data-action="duration:'+n+'" aria-pressed="'+(state.duration===n)+'">'+t+'<small>About '+n+' minutes</small></button>').join('')+'</div><div class="group">'+row('Set another duration','custom-duration','clock','Keep your own pace',state.duration+' min')+'</div><p class="fine">You can stop whenever you like. When your time is up, the article stays open. In this walkthrough, time moves ahead as you swipe.</p></div>';
        instrument({left:'clock',leftAction:'custom-duration',label:state.duration+' minutes',sub:'Next, choose what comes with you',action:'custom-duration',right:'Next',rightAction:'nav:setup-topics',rightIcon:'right',accent:true});
    }
    function setupTopics() {
        header('Your selection');
        const selected=plannedItems(),sources=[...new Set(selected.map(a=>a.source))];
        main.innerHTML='<div class="content setup-screen"><p class="eyebrow">Then, what interests you</p><h1>What are you<br>in the mood for?</h1><div class="scope-choices">'+[['Everything','A little of everything you follow','library'],['News & ideas','Vermont, politics and technology','book'],['A wider world','An illustrative landscape film','play'],['Vermont','Just the local stories','book']].map(([name,desc,ic])=>'<button class="scope-choice" data-action="scope:'+name+'" aria-pressed="'+(state.scope===name)+'">'+icon(ic)+'<span>'+name+'<small>'+desc+'</small></span>'+icon(state.scope===name?'check':'chevron')+'</button>').join('')+'</div>'+row('Fine-tune topics','topics','sliders',state.excluded.filter(t=>scopeTopics().includes(t)).length?'Some topics left out':'Everything in this selection is included')+'<div class="session-preview" aria-live="polite">'+(selected.length?'<span class="meta">Coming with you</span><div class="source-preview">'+selected.slice(0,3).map(a=>'<img src="'+a.image+'" alt="">').join('')+'<p>'+esc(sources.join(', '))+'</p></div>':'<h3>Bring something with you.</h3><p>Include a topic to make room for a story.</p>')+'</div><p class="fine">Short walkthrough: your choices shape the sample session. Time moves ahead as you swipe, so you can feel the ending without waiting.</p></div>';
        instrument({left:'sliders',leftAction:'topics',label:state.duration+' minutes',sub:state.scope,action:'nav:setup',right:'Begin',rightAction:'begin',rightIcon:'play',accent:true});
        bottom.querySelector('[data-action="begin"]').disabled=!selected.length;
    }
    function reader(id){const a=article(id);header(a.source);main.innerHTML='<article class="content reader"><div class="meta">'+esc(a.author)+' · '+a.dateLabel+'</div><h1>'+esc(a.title)+'</h1><figure class="reader-image">'+(a.kind==='video'?'<video controls playsinline preload="none" poster="'+a.image+'" src="assets/landscape-demo.mp4" aria-label="Illustrative landscape video"></video>':'<img data-full-image="'+a.id+'" src="'+a.image+'" alt="Article image from '+esc(a.source)+'" draggable="false">')+'</figure><div class="fine">Photo: '+esc(a.imageCredit||'Illustrative sample')+'</div><div class="reader-copy"><p>'+esc(a.teaser)+'</p></div><div class="reader-note" '+(a.kind==='video'?'hidden':'')+'><p class="fine">Length-matched preview paraphrase. This study shows the reading surface with real metadata and photography; it does not reproduce the full publisher article.</p><a class="quiet-link" href="'+esc(a.url||'#session')+'" target="_blank" rel="noopener noreferrer">Read the original at '+esc(a.source)+' ↗</a></div><div class="button-row">'+btn('Save to collection','save','secondary','bookmark')+btn('Share','share','secondary','share')+(!a.kind?btn('Full image','image:'+a.id,'quiet-link'):'')+'</div><div class="section-note">'+(a.kind==='video'?'Illustrative motion sample. The full app retains YouTube, Shorts and audio in its shared media surfaces.':'The full app keeps article extraction, retry, and the original-source link in this shared reader.')+'</div>'+(canAdvanceReader()?'<button class="reader-next" data-action="reader-next"><span class="reader-next-arrow">'+icon('arrowup')+'</span><span class="reader-next-copy">Swipe up for '+(state.cursor>=sessionItems().length-1||state.phase==='ended'?'the ending':'the next brief')+'</span><small>Or tap to continue</small></button>':'')+'</article>';instrument({left:'bookmark',leftAction:'save',label:origin==='session'?'Back to your session':'Back to '+({saved:'Saved',history:'History'}[origin]||'where you were'),sub:'Your place is kept',action:'back',right:'Back',rightAction:'back',rightIcon:'back'});}
    function library(){header('Library');main.innerHTML='<div class="content">'+resume()+'<h1>Choose what<br>fills your time.</h1><p class="lede">A few good sources, arranged around your interests.</p><div class="button-row">'+btn('Add source','nav:add','primary','plus')+btn('Import','nav:import','secondary')+'</div><div class="section-label"><h2>Your sections</h2><button data-action="organize">Organize</button></div><div class="group">'+row('News & ideas','nav:section/news','library','Vermont · Politics · Technology')+row('A wider world','nav:section/outdoors','library','Outdoors · Culture')+'</div>'+(state.customSources.length?'<h2>Added in this preview</h2><div class="group">'+state.customSources.map(s=>row(esc(s.name),'added-source','book',esc(s.topic))).join('')+'</div>':'')+'</div>';instrument({left:'more',leftAction:'library-menu',label:'Your library',sub:'Sources you chose',action:'library-menu',right:'Add',rightAction:'nav:add',rightIcon:'plus',accent:true});}
    function section(name){header(name==='outdoors'?'A wider world':'News & ideas');main.innerHTML='<div class="content">'+resume()+'<p class="eyebrow">Section</p><h1>'+ (name==='outdoors'?'A wider world':'News & ideas')+'</h1><p class="lede">Interests that belong together.</p><div class="group">'+(name==='outdoors'?['Outdoors','Culture']:['Vermont','Politics','Technology']).map(t=>row(t,'nav:topic/'+t,'library',t==='Vermont'?'VTDigger':t==='Politics'?'POLITICO':t==='Technology'?'404 Media':'Choose a source')).join('')+'</div></div>';instrument({left:'sliders',leftAction:'organize',label:'An interest at a time',sub:'Choose what belongs here',action:'organize',right:'Add',rightAction:'nav:add',rightIcon:'plus'});}
    function topic(name){header(name);const sources=[...new Set(articles.filter(a=>a.topic===name).map(a=>a.source))];main.innerHTML='<div class="content">'+resume()+'<p class="eyebrow">Topic</p><h1>'+esc(name)+'</h1><div class="group">'+(sources.map(s=>row(esc(s),'nav:source/'+encodeURIComponent(s),'book','Representation: '+(state.sourcePrefs[s]?.weight||'Normal'))).join('')||row('Add your first source','nav:add','plus'))+'</div>'+row('Topic settings','topic-settings','sliders','Archive defaults and section membership')+'</div>';instrument({left:'sliders',leftAction:'topic-settings',label:'Keep the balance yours',action:'topic-settings',right:'Add',rightAction:'nav:add',rightIcon:'plus'});}
    function source(name){header(name);const prefs=state.sourcePrefs[name]||{};main.innerHTML='<div class="content">'+resume()+'<p class="eyebrow">Source</p><h1>'+esc(name)+'</h1><div class="group">'+row('Representation','representation','sliders','How often this source appears',esc(prefs.weight||'Normal'))+row('Archive after','archive','clock','How long articles stay eligible',esc(prefs.archive||'30 days'))+row('Categories & keywords','filters','sliders','Exclude what you do not want in a session')+'</div><h2>From this source</h2>'+articles.filter(a=>a.source===name).map(itemRow).join('')+'</div>';instrument({left:'more',leftAction:'source-menu',label:'Your choice, your balance',sub:esc(name),action:'representation',right:'Edit',rightAction:'edit-source',rightIcon:'sliders'});}
    function saved(collection=''){header(collection||'Saved');const savedItems=items.filter(a=>(state.saved[a.id]||[]).length&&(!collection||state.saved[a.id].includes(collection)));if(sort==='published')savedItems.sort((a,b)=>(b.date||'').localeCompare(a.date||''));else savedItems.sort((a,b)=>(state.savedAt[b.id]||0)-(state.savedAt[a.id]||0));main.innerHTML='<div class="content">'+resume()+'<h1>'+(collection?esc(collection):'For another moment.')+'</h1>'+(!collection?'<div class="chips">'+state.collections.map(c=>btn(esc(c),'nav:collection/'+encodeURIComponent(c),'chip')).join('')+'</div>':'<p class="lede">A collection you can return to.</p>')+(savedItems.length?savedItems.map(itemRow).join(''):'<div class="empty">'+icon('bookmark')+'<h2>Room for something good.</h2><p>Save from an article’s options. It will wait here without becoming an unread count.</p>'+btn('Return to reading','nav:session','secondary')+'</div>')+'</div>';instrument({left:'more',leftAction:'collection-menu',label:collection||'Saved, without a deadline',sub:sort==='published'?'Ordered by publication':'Ordered by when you saved',action:'sort',right:collection?'Sort':'New',rightAction:collection?'sort':'new-collection',rightIcon:collection?'sliders':'plus'});}
    function you(){header('Your Otium');main.innerHTML='<div class="content">'+resume()+'<h1>Make it your own.</h1><p class="lede">A quiet place to adjust the way you read.</p><div class="group">'+row('Appearance','nav:appearance','sun','Typeface, reading size, and e-ink')+row('Reading history','nav:history','clock','What you opened or saved')+row('Insights','nav:insights','sliders','A description of your choices')+row('Settings','nav:settings','person','Session and media preferences')+'</div>'+row('About this study','study','book','Screen guide, sample content and limitations')+'</div>';appInstrument('Make it your own');}
    function history(){header('Reading history');let list=historyFilter==='Saved'?items.filter(a=>state.saved[a.id]?.length):state.history.map(id=>article(id));main.innerHTML='<div class="content"><h1>Where you spent<br>your attention.</h1><div class="chips">'+['Read','Shown','Saved'].map(t=>'<button class="chip" data-action="history-filter:'+t+'" aria-pressed="'+(historyFilter===t)+'">'+t+'</button>').join('')+'</div>'+(historyFilter==='Shown'?sessionItems().slice(0,state.cursor+1).filter(a=>!a.kind).map(itemRow).join(''):list.map(itemRow).join(''))+(!list.length&&historyFilter!=='Shown'?'<p class="lede">Open an article in the preview to see it here.</p>':'')+'<p class="fine">History in this study records only your local preview actions. No account history is loaded.</p></div>';appInstrument('Where you spent your time');}
    function insights(){header('Insights');main.innerHTML='<div class="content"><p class="eyebrow">Illustrative composition</p><h1>A little perspective.</h1><p class="lede">A description of what is here, never a score to improve.</p><h2>The sources in this study</h2>'+[['Vermont','VTDigger',''],['Politics','POLITICO','alt'],['Technology','404 Media','last']].map(([t,s,c])=>'<div class="stat-line"><span class="swatch-line"><i class="swatch '+c+'"></i>'+t+'</span><span>'+s+'</span></div>').join('')+'<h2>The balance is yours.</h2><p class="lede">Representation changes how much room a source gets. It does not learn from how long you linger.</p>'+btn('Adjust your sources','nav:library','secondary','sliders')+'</div>';appInstrument('A little perspective');}
    function appearance(){header('Appearance');main.innerHTML='<div class="content"><h1>A comfortable page.</h1><p class="lede">Keep the words easy to spend time with.</p><div class="group">'+row('Typeface','typography','book','Fraunces titles · Newsreader reading','')+row('Reading size','reading-size','sliders','Headline scale stays restrained',state.readingSize+'px')+'</div><div class="group"><label class="check-row"><input type="checkbox" data-setting="eink" '+(state.eink?'checked':'')+'><span class="copy">E-ink presentation<small>Light paper, dark text, grayscale, immediate changes.</small></span></label></div><div class="font-preview"><div class="lab-label">Live reading sample</div><h3>'+esc(current().title)+'</h3><p>'+esc(current().teaser)+'</p></div><p class="fine">The production appearance controls for measure, spacing, card detail and image preferences remain in scope. This round focuses on type and the Afterglow surfaces.</p></div>';instrument({left:'sun',leftAction:'typography',label:'Comfort over display',action:'typography',right:'Done',rightAction:'nav:you',rightIcon:'check'});}
    function settings(){header('Settings');main.innerHTML='<div class="content"><h1>Your pace. Your choices.</h1><div class="group">'+row('Default session','custom-duration','clock','Time is shown precisely here',state.duration+' min')+row('Session check-in','checkin','sliders','An explicit pause, never silent re-ranking')+row('YouTube watch history','youtube','play','Choose whether playback is associated with your account')+row('Appearance','nav:appearance','sun','Reading and device preferences')+'</div><p class="fine">This prototype stores preferences locally. Production authentication and account controls are unchanged.</p></div>';instrument({left:'sliders',leftAction:'checkin',label:'Settings for your attention',action:'checkin',right:'Done',rightAction:'nav:you',rightIcon:'check'});}
    function add(){header('Add a source');main.innerHTML='<div class="content"><h1>Something worth<br>following.</h1><p class="lede">Give it a place in your library.</p><form id="add-form">'+field('Name','source-name','','text')+field('Feed, channel or podcast URL','source-url','','url')+'<label class="field" for="source-topic">Topic</label><select id="source-topic" name="topic">'+['Vermont','Politics','Technology','Outdoors'].map(x=>'<option>'+x+'</option>').join('')+'</select><div class="button-row"><button class="primary" type="submit">Review source '+icon('right')+'</button></div></form><p class="fine">Preview only: no feed is fetched and no account source is created. The production flow retains feed discovery, YouTube search and podcast support.</p></div>';instrument({left:'plus',leftAction:'focus-add',label:'A source you choose',sub:'First, its home in your library',action:'focus-add',right:'Review',rightAction:'submit-add',rightIcon:'right'});}
    function importPage(){header('Import sources');main.innerHTML='<div class="content"><h1>Bring the good parts<br>with you.</h1><p class="lede">Review what is coming in before you add it.</p><label class="field" for="opml">OPML file</label><input id="opml" type="file" accept=".opml,.xml"><h2>Or paste feed URLs</h2><textarea id="import-urls" aria-label="Feed URLs, one per line" placeholder="One URL per line"></textarea><div class="button-row">'+btn('Preview import','preview-import','primary','right')+'</div><p class="fine">This study previews OPML and URL lists locally. Production also keeps its YouTube Takeout import.</p></div>';instrument({left:'library',leftAction:'preview-import',label:'Review before adding',sub:'Your library stays yours',action:'preview-import',right:'Review',rightAction:'preview-import',rightIcon:'right'});}
    function ending(){header('',false);main.innerHTML='<div class="content session-end"><span class="mark">'+mark+'</span><h1>A good place to stop.</h1><p class="lede">You made some room.<br>The rest can wait.</p>'+(state.sessionPlan?'<p class="session-recap">'+esc(state.sessionPlan.scope)+' · The time was yours.</p>':'')+'<div class="group">'+row('Return to something you saved','nav:saved','bookmark','Nothing here needs catching up.')+'</div><div class="button-row">'+btn('Leave it here','nav:home','primary')+btn('A little more','continue','secondary')+'</div>'+btn('Choose a new session','nav:setup','quiet-link')+'<p class="fine">Continuing is a choice. There is no automatic next session.</p></div>';instrument({left:'check',leftAction:'nav:home',label:'That was your time',sub:'No next thing waiting',action:'nav:home',right:'Finish',rightAction:'nav:home',rightIcon:'check'});}
    function render(){const previousRoute=route;rendering=true;pause();if(sheet.open)closeSheet(false);if(viewer.open)closeImage(false);window.dispatchEvent(new Event("otium:navigate"));observer?.disconnect();route=decodeURIComponent(location.hash.slice(1)||'start');const [view,...rest]=route.split('/'),key=rest.join('/');main.className='';main.scrollTop=0;bottom.hidden=false;({session,home,start,setup,'setup-topics':setupTopics,library,you,history,insights,appearance,settings,add,import:importPage,end:ending}[view]||(()=>{if(view==='reader')reader(key);else if(view==='section')section(key);else if(view==='topic')topic(key);else if(view==='source')source(key);else if(view==='saved')saved();else if(view==='collection')saved(key);else home();}))();applyFont();if(previousRoute&&previousRoute!==route&&motionAllowed())main.animate([{opacity:.4,transform:'translateX(6px)'},{opacity:1,transform:'translateX(0)'}],{duration:170,easing:'ease-out'});if(view!=='session')rendering=false;}
    function sourceName(){if(route.startsWith('source/'))return decodeURIComponent(route.slice(7));return (route.startsWith('reader/')?article(route.slice(7)):current()).source;}
    function articleMenu(){const a=route.startsWith('reader/')?article(route.slice(7)):current();showSheet('This article','<p class="meta">'+esc(a.source)+'</p><h3 style="margin-top:4px">'+esc(a.title)+'</h3><div class="group">'+row('Save to a collection','save','bookmark','Keep it for another moment')+row('Share article','share','share')+(!a.kind?row('View full image','image:'+a.id,'search'):'')+row('Why this appeared','why','sliders')+row('About this source','source-current','book')+'</div><div class="group">'+row('Change representation','representation','sliders','More or less room for this source')+row('Categories & keywords','filters','sliders','Fine-tune what makes it into a session')+'</div>');}
    function saveSheet(){const a=route.startsWith('reader/')?article(route.slice(7)):current();const selected=state.saved[a.id]||[];showSheet('Save for another moment','<p class="fine">Choose one or more collections.</p><div class="group">'+state.collections.map(c=>'<label class="check-row"><input type="checkbox" data-collection="'+esc(c)+'" data-item="'+a.id+'" '+(selected.includes(c)?'checked':'')+'><span class="copy">'+esc(c)+'</span></label>').join('')+'</div><div class="button-row">'+btn('New collection','new-collection','secondary','plus')+btn('Done','save-done','primary','check')+'</div>');}
    function study(){showSheet('A closer look at Afterglow','<p class="fine">Design prototype. Real publisher metadata and images; length-matched teaser paraphrases. Account controls are local simulations. The video is an illustrative motion sample.</p><h3>Explore an experience</h3><div class="study-screen-grid">'+[['session','The session'],['start','Start from the beginning'],['setup','Choose a session'],['reader/'+current().id,'The reader'],['library','Library'],['source/VTDigger','Source controls'],['saved','Saved'],['history','History'],['insights','Insights'],['appearance','Appearance'],['end','A natural ending']].map(([r,t])=>btn(t,'study-nav:'+r,'')).join('')+'</div><h3>Preview a moment in time</h3><div class="chips">'+[['settle','Settling in'],['middle','A little time left'],['last','One more'],['ended','Time is yours again']].map(([k,t])=>btn(t,'phase:'+k,'chip')).join('')+'</div><p class="fine">These buttons simulate the time phases. Sessions started in this walkthrough move time ahead as you swipe; the original full fixture comparison uses elapsed time. There is no second-by-second display, article counter or progress bar.</p><div class="button-row">'+btn('Type & reading','typography','primary')+'</div><a class="quiet-link" href="notes.html">Design notes, sources and scope ↗</a><br><a class="quiet-link" href="https://quiver.fisher.sh/static/reports/otium/2026-10-16-afterglow-feedback/?annotate">Leave flow feedback ↗</a>');}
    async function action(a){
        if(a==='image-close'){closeImage();return;}if(a.startsWith('image:')){revealImage(a.slice(6));return;}if(a==='reader-next'){advanceReader();return;}
        if(a==='close'){closeSheet();return;}if(a==='back'){goBack();return;}if(a.startsWith('nav:')){navigate(a.slice(4));return;}if(a.startsWith('study-nav:')){if(a.includes('reader/'))origin='session';navigate(a.slice(10));return;}
        if(a==='typography'){typography();return;}if(a==='study'){study();return;}
        if(a.startsWith('font:')){state.font=a.slice(5);applyFont();typography();return;}
        if(a==='font-prev'||a==='font-next'){let i=fonts.findIndex(f=>f.id===state.font);state.font=fonts[(i+(a==='font-next'?1:fonts.length-1))%fonts.length].id;applyFont();return;}
        if(a==='audition'){state.audition=true;closeSheet();applyFont();return;}if(a==='audition-close'){state.audition=false;applyFont();return;}
        if(a==='app-menu'){showSheet('Your Otium','<div class="group">'+row('Home','nav:home','book')+(state.active?row('Return to session','nav:session','play'):row('Start a new session','nav:setup','clock'))+row('Library','nav:library','library')+row('Saved','nav:saved','bookmark')+row('Your Otium','nav:you','person')+'</div>'+row('Explore this study','study','sliders'));return;}
        if(a==='topics-done'){closeSheet();if(route==='setup-topics')setupTopics();return;}if(a==='begin'){begin();return;}if(a==='next'){next();return;}if(a.startsWith('read:')){const id=a.slice(5);origin=route;state.readerOrigin=origin;state.history=[id,...state.history.filter(x=>x!==id)];if(origin==='session')state.sessionOpened=[...new Set([...state.sessionOpened,id])];persist();navigate('reader/'+id);return;}
        if(a==='article-menu'){articleMenu();return;}if(a==='save'){saveSheet();return;}if(a==='save-done'){persist();closeSheet();toast('Collections saved in this preview');if(route.startsWith('saved')||route.startsWith('collection'))render();return;}
        if(a==='session-menu'){showSheet('Your session','<h3>'+phrase()+'</h3><p class="fine">'+(state.sessionPlan?.duration||state.duration)+' minute intention · '+esc(state.sessionPlan?.scope||state.scope)+'. The article stays open when time runs out. You choose when to leave.</p><div class="group">'+row('Keep reading','close','book')+row('End this session','end-session','check')+row('Visit your library','nav:library','library','Your place will be kept')+row('Preview a different time phase','study','clock')+'</div>');return;}
        if(a==='end-session'){finishSession();return;}
        if(a==='continue'){showSheet('A little more time','<p class="lede">Only if you want it.</p><div class="button-row">'+btn('Five more minutes','extend:5','primary')+btn('Ten more minutes','extend:10','secondary')+'</div><p class="fine">This short walkthrough repeats matching sample content. Production requests additional session items.</p>');return;}
        if(a.startsWith('extend:')){state.duration=Number(a.slice(7));if(state.sessionPlan){state.scope=state.sessionPlan.scope;state.excluded=[...state.sessionPlan.excluded];}begin();return;}
        if(a.startsWith('phase:')){state.phase=a.slice(6);phasePreview=true;persist();closeSheet();navigate('session');return;}
        if(a.startsWith('duration:')){state.duration=Number(a.slice(9));persist();setup();return;}if(a.startsWith('scope:')){state.scope=a.slice(6);persist();setupTopics();return;}
        if(a==='custom-duration'){showSheet('Your own pace','<form id="duration-form">'+field('Minutes','minutes',state.duration,'number')+'<p class="fine">Set the duration here. The reading bar describes the remaining time in words.</p><button class="primary" type="submit">Use this time</button></form>');$('#minutes').min='1';$('#minutes').max='180';return;}
        if(a==='topics'){showSheet('Choose what comes with you','<p class="fine">Changing scope does not start a session.</p><div class="group">'+scopeTopics().map(t=>'<label class="check-row"><input type="checkbox" data-topic="'+t+'" '+(!state.excluded.includes(t)?'checked':'')+'><span class="copy">'+t+'</span></label>').join('')+'</div><div class="button-row">'+btn('Done','topics-done','primary')+'</div>');return;}
        if(a==='source-current'){navigate('source/'+encodeURIComponent(sourceName()));return;}
        if(a==='why'){showSheet('Why this appeared','<h3>Because you chose the source.</h3><p class="reader-copy">Representation determines how much room a source gets. Otium then selects a recent eligible article from that source.</p><p class="fine">This walkthrough selects from a small sample using your chosen topics and time. Production also uses source representation and eligibility. Reading behavior never changes the mix.</p>'+row('Adjust representation','representation','sliders')+row('About this source','source-current','book'));return;}
        if(a==='representation'||a==='archive'){const name=sourceName(),key=a==='representation'?'weight':'archive',values=key==='weight'?['Much less','Less','Normal','More','Much more']:['Inherit','7 days','30 days','90 days','Evergreen'];showSheet(a==='representation'?'Give it the right amount of room':'Keep what is still relevant','<p class="meta">'+esc(name)+'</p><div class="group">'+values.map(v=>row(v,'pref:'+key+':'+v,'check','',state.sourcePrefs[name]?.[key]===v?'Selected':'')).join('')+'</div><p class="fine">Changes are stored only in this preview.</p>');return;}
        if(a.startsWith('pref:')){const [,key,...v]=a.split(':');const name=sourceName();state.sourcePrefs[name]={...state.sourcePrefs[name],[key]:v.join(':')};persist();closeSheet();if(route.startsWith('source/'))render();toast('Source preference saved');return;}
        if(a==='filters'){showSheet('Leave out what does not fit','<form id="filters-form">'+field('Exclude keywords','keywords',state.sourcePrefs[sourceName()]?.keywords||'')+'<p class="fine">Separate keywords with commas. The production filter also supports feed categories.</p><div class="group">'+['Opinion','Sponsored'].map(c=>'<label class="check-row"><input type="checkbox" name="category" value="'+c+'" '+((state.sourcePrefs[sourceName()]?.categories||[]).includes(c)?'checked':'')+'><span class="copy">Exclude '+c.toLowerCase()+'</span></label>').join('')+'</div><button class="primary" type="submit">Save filters</button></form>');$('#keywords').required=false;return;}
        if(a==='new-collection'){showSheet('A place to return to','<form id="collection-form">'+field('Collection name','collection-name')+'<div class="button-row"><button class="primary" type="submit">Create collection</button></div></form>');return;}
        if(a==='sort'){showSheet('Put them in order','<div class="group">'+row('When saved','sort:saved','clock','',sort==='saved'?'Selected':'')+row('When published','sort:published','book','',sort==='published'?'Selected':'')+'</div>');return;}
        if(a.startsWith('sort:')){sort=a.slice(5);closeSheet();render();return;}
        if(a==='collection-menu'){showSheet('Your collections','<div class="group">'+row('New collection','new-collection','plus')+row('Sort articles','sort','sliders')+row('Manage collections','manage-collections','bookmark')+'</div>');return;}
        if(a==='manage-collections'){showSheet('Manage collections','<div class="group">'+state.collections.map(c=>row(esc(c),'rename:'+c,'bookmark','Rename or remove this collection')).join('')+'</div>');return;}
        if(a.startsWith('rename:')){const c=a.slice(7);showSheet('Edit collection','<form id="rename-form" data-original="'+esc(c)+'">'+field('Name','rename-name',c)+'<div class="button-row"><button class="primary" type="submit">Save name</button>'+btn('Remove collection','remove-collection:'+c,'secondary danger')+'</div></form>');return;}
        if(a.startsWith('remove-collection:')){const c=a.slice(18);state.collections=state.collections.filter(x=>x!==c);Object.keys(state.saved).forEach(id=>state.saved[id]=state.saved[id].filter(x=>x!==c));persist();navigate('saved');toast('Collection removed from preview');return;}
        if(a.startsWith('history-filter:')){historyFilter=a.slice(15);history();return;}
        if(a==='reading-size'){showSheet('Reading size','<div class="choice-grid">'+[17,19,21,23].map(n=>'<button class="choice" data-action="text-size:'+n+'" aria-pressed="'+(state.readingSize===n)+'" style="font-size:'+n+'px">A comfortable page<small>'+n+' pixels</small></button>').join('')+'</div>');return;}
        if(a.startsWith('text-size:')){state.readingSize=Number(a.slice(10));applyFont();closeSheet();return;}
        if(a==='checkin'||a==='youtube'){const key=a==='checkin'?'checkin':'youtube';showSheet(a==='checkin'?'An occasional check-in':'Your YouTube history','<p class="reader-copy">'+(a==='checkin'?'If you are moving quickly through stories, Otium can offer a visible pause. It never silently changes the mix.':'Choose whether the production player uses your signed-in YouTube context. No YouTube account is used in this preview.')+'</p><label class="check-row"><input type="checkbox" data-setting="'+key+'" '+(state[key]?'checked':'')+'><span class="copy">'+(key==='checkin'?'Offer a check-in':'Associate playback with my account')+'</span></label>'+btn('Done','close','primary'));return;}
        if(a==='library-menu'||a==='organize'){showSheet('Give your library some shape','<div class="group">'+row('Add source','nav:add','plus')+row('Import sources','nav:import','library')+row('Edit section or topic','topic-settings','sliders')+'</div>');return;}
        if(a==='topic-settings'){showSheet('Topic settings','<form id="topic-form">'+field('Topic name','topic-name',route.startsWith('topic/')?route.slice(6):'Vermont')+'<label class="field" for="section-name">Section</label><select id="section-name"><option>News & ideas</option><option>A wider world</option></select><label class="field" for="topic-archive">Default archive period</label><select id="topic-archive"><option>30 days</option><option>7 days</option><option>Evergreen</option></select><div class="button-row"><button class="primary" type="submit">Preview changes</button></div></form>');return;}
        if(a==='source-menu'){showSheet('Source options','<div class="group">'+row('Edit source','edit-source','sliders')+row('Representation','representation','sliders')+row('Categories & keywords','filters','sliders')+row('Remove source','remove-source','close')+'</div>');return;}
        if(a==='edit-source'){showSheet('Edit source','<form id="edit-source-form">'+field('Source name','edit-source-name',sourceName())+'<label class="field" for="edit-topic">Topic</label><select id="edit-topic"><option>Vermont</option><option>Politics</option><option>Technology</option></select><div class="button-row"><button class="primary" type="submit">Preview changes</button></div></form>');return;}
        if(a==='remove-source'){showSheet('Remove this source?','<p class="reader-copy">It would stop appearing in future sessions. Saved articles would remain in your collections.</p><p class="fine">The fixed comparison fixtures remain available in this study.</p><div class="button-row">'+btn('Keep source','close','primary')+btn('Preview removal','remove-demo','secondary danger')+'</div>');return;}
        if(a==='remove-demo'){closeSheet();toast('Removal previewed. Fixtures kept.');return;}
        if(a==='focus-add'){$('#source-name')?.focus();return;}if(a==='submit-add'){$('#add-form')?.requestSubmit();return;}
        if(a==='added-source'){showSheet('Added in this preview','<p class="lede">This source is stored locally for the design walkthrough. The production flow would fetch its feed after confirmation.</p>'+btn('Done','close'));return;}
        if(a==='preview-import'){const file=$('#opml')?.files[0],urls=$('#import-urls')?.value||'';importDraft=[];if(file){const xml=new DOMParser().parseFromString(await file.text(),'application/xml');if(xml.querySelector('parsererror')){toast('That file could not be read as OPML');return;}importDraft=[...xml.querySelectorAll('outline[xmlUrl]')].map(x=>({name:x.getAttribute('title')||x.getAttribute('text')||x.getAttribute('xmlUrl'),url:x.getAttribute('xmlUrl'),topic:'Imported'}));}else{for(const value of urls.split(/\n/).map(x=>x.trim()).filter(Boolean)){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))throw Error();importDraft.push({name:u.hostname,url:u.href,topic:'Imported'});}catch{toast('Use complete http or https feed URLs');return;}}}if(!importDraft.length){toast('Choose an OPML file or paste a feed URL');return;}showSheet('Review your import','<p class="fine">'+importDraft.length+' sources. Nothing has been added yet.</p><div class="group">'+importDraft.map(x=>'<div class="row"><span class="copy">'+esc(x.name)+'<small>'+esc(x.url)+'</small></span></div>').join('')+'</div>'+btn('Add to this preview','confirm-import','primary','plus'));return;}
        if(a==='confirm-import'){state.customSources.push(...importDraft);persist();navigate('library');toast('Sources added to this preview');return;}
        if(a==='media-notes'){showSheet('Room around the picture','<p class="reader-copy">An inset player that starts paused. Its own controls handle playback. Moving to the next brief pauses it.</p><p class="fine">This is a short motion study from a landscape photograph, not a publisher video or a connected YouTube player. Production retains YouTube, Shorts and audio support.</p><div class="button-row">'+btn('Try portrait framing','portrait','secondary')+btn('Back to the film','close','primary')+'</div>');return;}
        if(a==='portrait'){closeSheet();main.querySelector('video')?.closest('.media').classList.toggle('portrait');fitBriefs();return;}
        if(a==='share'){const x=route.startsWith('reader/')?article(route.slice(7)):current();try{if(navigator.share)await navigator.share({title:x.title,url:x.url||location.href});else{await navigator.clipboard.writeText(x.url||location.href);toast('Article link copied');}}catch(e){if(e.name!=='AbortError')toast('Open the original article to share its link');}return;}
    }
    document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b.dataset.action);}});
    document.addEventListener('change',e=>{const t=e.target;if(t.dataset.setting){state[t.dataset.setting]=t.checked;applyFont();}if(t.dataset.collection){const id=t.dataset.item,c=t.dataset.collection;const values=state.saved[id]||[];if(t.checked&&!values.length)state.savedAt[id]=Date.now();state.saved[id]=t.checked?[...new Set([...values,c])]:values.filter(x=>x!==c);persist();}if(t.dataset.topic){state.excluded=t.checked?state.excluded.filter(x=>x!==t.dataset.topic):[...new Set([...state.excluded,t.dataset.topic])];persist();if(route==='setup-topics')setupTopics();}});
    document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='duration-form'){state.duration=Number($('#minutes').value);persist();closeSheet();if(route==='setup')setup();else if(route==='setup-topics')setupTopics();else if(route==='settings')settings();}if(f.id==='collection-form'){const name=$('#collection-name').value.trim();if(!name)return;if(state.collections.includes(name)){toast('That collection already exists');return;}state.collections.push(name);persist();if(route.startsWith('reader/')||route==='session')saveSheet();else{closeSheet();render();}}if(f.id==='rename-form'){const old=f.dataset.original,name=$('#rename-name').value.trim();if(!name||state.collections.includes(name)&&name!==old){toast('Choose a unique collection name');return;}state.collections=state.collections.map(x=>x===old?name:x);Object.keys(state.saved).forEach(id=>state.saved[id]=state.saved[id].map(x=>x===old?name:x));persist();navigate('saved');}if(f.id==='filters-form'){const name=sourceName();state.sourcePrefs[name]={...state.sourcePrefs[name],keywords:$('#keywords').value,categories:[...f.querySelectorAll('[name=category]:checked')].map(x=>x.value)};persist();closeSheet();toast('Filters saved in this preview');}if(f.id==='add-form'){const name=$('#source-name').value.trim(),url=$('#source-url').value,topic=$('#source-topic').value;try{if(!['http:','https:'].includes(new URL(url).protocol))throw Error();}catch{toast('Use a complete http or https URL');return;}importDraft=[{name,url,topic}];showSheet('Ready to add','<h3>'+esc(name)+'</h3><p class="meta">'+esc(url)+'</p><p>In '+esc(topic)+'. Representation starts at Normal.</p><p class="fine">This adds a local preview source only.</p>'+btn('Add source','confirm-import','primary','plus'));}if(f.id==='topic-form'||f.id==='edit-source-form'){closeSheet();toast('Structure edit previewed. Fixtures kept.');}});
    viewer.addEventListener('cancel',e=>{e.preventDefault();closeImage();});sheet.addEventListener('cancel',e=>{e.preventDefault();closeSheet();});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('hashchange',render);window.addEventListener('resize',()=>{const index=state.cursor;fitBriefs();if(route==='session')main.scrollTop=index*main.clientHeight;});
    setInterval(()=>{if(!state.active||!state.started||phasePreview||state.sessionPlan)return;const fraction=(Date.now()-state.started)/(state.duration*60000);const phase=fraction>=1?'ended':fraction>.8?'last':fraction>.35?'middle':'settle';if(phase!==state.phase){state.phase=phase;persist();if(route==='session')sessionInstrument();}},15000);
    if(!state.started)state.started=Date.now();
    window.afterglow={state,fonts,items,navigate,action,fit:fitBriefs,sessionItems,plannedItems,revealImage,closeImage,canAdvanceReader,advanceReader,goBack};
    render();
})();
